from author_library import *
cards=[]
cards.append(compact('yin_dade','殷大德','殷大德后来是经营跨国银行的金融巨子，年轻时却在边疆替有势力的皇族贩运烟土，熟悉关节、江湖规矩和以钱解决危机的办法。一队败兵拦住他的马帮，杀害同伴并逼问货物藏处，他明知吐露也未必生还，在恐惧中拖延到白老大出现。白老大杀死施暴的团长，要求他把货物分给败兵，他立即答应，竟从俘虏变成带着护卫越境的商人。多年后在宴会上，他一眼认出救命恩人就是昔日阳光土司，却遭白老大坚决否认；银行家的威仪被感激和困惑完全打乱。白素兄妹来访，他愿意奉上珍贵藤杖，耐心说出所见的婴儿和边疆旧事，但也承认没有见过他们的母亲。他的苗疆联系和会翻译的身份，使那位小个子保镖的经历逐渐可以被理解；后来白奇伟追问独目天王，他继续协助，不将不知道的事情假装知道。卡片不把他简化为无害慈善家，旧日烟土生意是财富道路的一部分；也不把从失败士兵中生还写成他肉身强大。终局仍是能安排资源、顾念恩情、愿对自己知道的往事负责的老人，武力保护须另有实际同伴。','后续仍以银行家与苗疆联络者身份协助查访；未见死亡或超常变化','主角／重要配角','报答救命恩情，维护生意和可继续往来的关系','热情招待，愿给切实帮助，叙述自己亲历的场面','遇到死亡威胁先拖延谈价，局势改变则迅速接受能保命的安排','知恩不等于知道恩人的全部秘密，明确区分见过与猜测',[ab('边疆商务与联络','长期经营、通晓当地交往，能翻译保镖语言和提供查访条件','依赖关系与对方意愿；财富不等于拥有军队或蛊术')],[ev('086',973,1047,'认出救命恩人遭否认'),ev('086',1173,1242,'款待、藤杖与翻译'),ev('086',1254,1268,'烟土商务背景'),ev('086',1305,1450,'遭劫、获救和分货'),ev('087',715,842,'翻译保镖经历')],profile='expert'))
cards.append(compact('yin_bodyguard','殷大德的小个子保镖','这名未具姓名的裸裸族保镖身材极小、黝黑而敏捷，日常沉默地跟在殷大德身后，既能在突发冲突中显示身手，也会为一杯珍贵的家乡果酒露出孩子般的欣喜。他不是只会服从命令的工具：涉及师承时，他坚持自己曾在烈火前发誓，无论金钱还是追逼都不能让他说出秘密，甚至宁可离开雇主。白奇伟改用点头摇头的问法，才从他有限回答中确认，他十岁时受一名女子传授武艺，时间在白老大离开苗疆四年之后。他不知道陈月兰的名字，把师父视为天上仙人，见过灵猴抬她越过峭壁，却不能指出她的住处。独目天王和女师的关系是调查者结合多项证据推论，不是保镖本人自称已掌握完整谱系。他跟随殷大德多年，在现代城市仍保有故乡的信仰与礼节，外人看他简单，并不意味着他没有守密和选择的能力。综合卡使他成为行动迅速、忠诚却有边界的护卫和珍贵见证者；不能把他对神仙的解释直接当作他有天界知识，更不能因师父与灵猴有关，就给他控制所有野兽的本领。','继续随殷大德活动；师父去向不知，未获得新科技或异星能力','重要配角','保护雇主，遵守师承誓言，保全自己认可的关系','少说话、迅速做事，对善意和家乡物产会直接表示感谢','身体威胁时凭敏捷护卫；被逼问誓言内容则拒绝甚至离开','可回答亲历细节而不越过守密底线，对不懂的科技保留自身解释',[ab('敏捷武术与护卫','受高明女子传授武艺，能快速移位、纵跃和近身制止','人类肉身仍会受伤；不继承师父未知能力，也无证据能控制灵猴')],[ev('086',1021,1052,'随护与初次冲突'),ev('086',1187,1242,'侍立、果酒与忠诚'),ev('087',728,808,'守誓、纵跃与授艺时地'),ev('087',819,846,'不知道师父住处、所见灵猴及年龄')],profile='martial'))
cards.append(compact('tanxian_bad_colonel','劫殷大德的败兵团长','这名上校团长率领约百名败兵出没边疆，左臂裹着带血绷带，身材高大，手持冲锋枪。他从土匪当成军官，败退没有使他收敛，反使他把劫夺烟土当作补偿战场失利的办法。抓住殷大德的同伴后，他用残酷处置迫使领队交代藏货地点，又坦白承诺即使说出也只是给个痛快，显示他的威吓不是可以轻易谈成安全交易的假动作。殷大德试图以钱和越境安顿拖延，他有武器和人数，却没有独立于局势的绝对忠诚。白老大以阳光土司身份出现，许多败兵认出并敬畏这位地方名人，团长命众人一起上，自己却后退准备从容行动，结果没有一人听命。他这才想举枪，已经被白老大踢飞武器，再一肘击出悬崖，惨叫消失。卡片保留伤兵的身体限制、依靠部属的实际条件和遇更强威望时迅速失势的可能，不以残忍增加额外抗性，也不将整个百人队的火力压缩成他随身能力。他与后来携金币逃亡并向卫提供证词的团长是两个人，不能把后者的生还故事接在他的终局之后。','被白老大击落悬崖死亡；恢复最后可行动但左臂受伤的形态，保留败亡事实','反派','抢到物资和钱财，维持残兵中的支配地位','以枪械和部下人数压迫弱者，许诺仅为促使对方服从','真正遇到强手先命部下挡前，若失去服从便急于亲自举枪','不把残兵对他的服从当作永恒事实；威望和求生会改变他们的选择',[ab('枪械与残部指挥','携冲锋枪、以军衔命令部下实施拘禁与抢掠','左臂已有伤；枪需举起瞄准，近身被夺和士兵拒令均可使其失势')],[ev('086',1305,1347,'外观、伤势、劫夺与施暴'),ev('086',1379,1399,'命令失败、举枪不及及死亡')],profile='investigator'))
cards.append(compact('coin_colonel','携金币出逃的团长','这名后来潦倒的老团长曾参加攻入陈天豪帅府的部队，但自称筹划背叛的是更高级军官，自己只在乱局中被一箱三千枚金币吸引。他没有继续追求升官，带两个连长抬箱离队，向苗疆逃去。按其叙述，两个同伴图谋杀他独吞，他先发制人开枪杀了二人，自己也带伤滚下斜坡，金币箱几乎把他压向悬崖。白老大偶然经过救了他，箱子破裂，绝大多数金币散落深渊，只剩一枚交回他手中。救命者问起坠落的飞机和帅府变故，又与幼子说话，这些当时对他无关紧要的细节，多年后却成为白家寻母的重要线索。晚年的他住简陋石屋、满身酒气，直到实在过不下去才卖掉唯一金币。起初他不愿平白回答盘问，得知白素是恩人的女儿，立即改为尽力回忆，后来还带来旧侍卫陈水补充情况。他会夸张，有贪念和杀人的旧事，也能记恩。卡片以老年体况为准，保留枪械和军旅经验而不恢复年轻兵力，所述两连长谋害仍标为他的证词，不能把一个讲述者写成全知历史旁白。','晚年仍在人间、生活潦倒并提供证词；以当前老年身体演绎，不恢复旧部或遗失金币','主角／重要配角','维持生计并偿还救命之恩，对自己当年的选择保留辩解','喝酒说旧事，喜欢用江湖话和夸张动作强调经历','有人盘问时先计较凭什么，认出恩人关系后愿真诚协助','记忆可提供关键细节，但个人杀人理由仍需旁证',[ab('军旅经验与旧事证言','曾用枪参与乱军行动，能记下地形、交谈和人物习惯','老年体力与贫困限制当前行动；无现役军队，证词可能含夸张')],[ev('086',2969,2991,'携金币、杀同伴与售币'),ev('086',2995,3032,'晚年生活及叙述习惯'),ev('086',3033,3091,'获救、余币和关键对话'),ev('087',329,365,'带陈水来补证')],profile='ordinary'))
cards.append(compact('chen_shui','陈水','陈水曾是陈天豪的警卫队长和贴身侍卫，年轻时身形强壮、拳头硕大，对自己的武功和在帅府的地位颇有自信。他不服那个瘦小独眼的副队长边花儿得到大帅重视，想找机会一试高下，却被大帅直接禁止；这种不服和嫉妒并没有使他真正了解对方的本领。陈月兰成年后不肯接受父亲的安排，陈水在帅府亲见旁人的倾慕和旧关系，也记得大小姐对边花儿的尊重。他后来与昔日团长来到卫斯理家，已经消瘦，声音嘶哑，不愿只谈年轻时如何威武，却会在酒和故人面前重新显出往日情绪。他叙述大帅遇袭时，能把边花儿抢救二小姐的细节、临终嘱托和人员关系说出，为白家寻找母系来历补上关键一段。卡片不是把一个回忆中的侍卫恢复成常年巅峰，而是留下衰老的人仍执着旧尊严、仍为曾经不服的同僚作证的变化。他的武术只按普通训练和自述程度，不因大帅一句夸赞或他自己不服，就判定能击败独目天王；他也没有解释异星飞船或烈火女的知识。','晚年向卫斯理提供帅府旧事，身体已消瘦；没有回归军旅或获得超常能力','阶段叙事主角','保存当年大帅与同僚的真相，同时维护自己的尊严','以军旅口吻说往事，遇旧友和好酒才逐渐打开话匣','被轻视时会争强，却能在真实经历面前承认他人行动','不服气与实际胜负分开；本人未能目击的后续不装作知道',[ab('警卫经验与人物记忆','熟悉帅府警卫、人物关系和武术场面，提供临终托付证词','当前老年身体与记忆范围有限；未展示后来能继续发挥青年巅峰武力')],[ev('087',329,365,'警卫身份、晚年形态与来访'),ev('087',449,490,'不服边花儿却被制止'),ev('087',548,608,'帅府遇袭和托孤经历')],profile='ordinary'))
cards.append(compact('chen_tianhao','陈天豪','陈天豪是掌握大批军队的川西督军，也是陈月兰和陈月梅的父亲。在外人眼中，他是大帅府的权力中心，军官和江湖大爷都要看他的脸色；面对女儿，他却会被洋化、独立又身怀武艺的月兰弄得恼怒和无奈。他欣赏忠勇，也保留强烈等级观念，对来路神秘的边花儿特别信任，因为对方曾背他脱离险境，又救过幼年的月兰。他知道看似弱小的护卫有真正本事，禁止陈水因嫉妒挑衅，这份判断比部下只看体格更准确。月兰远走后，他从金贩的见闻追索女儿，得知她与白老大同行，怒意、父爱和对婚姻的控制混在一起。最后下属两个师的高级军官倒戈，帅府在新年遭袭，他中枪濒死，清楚自己难以逃生，把小女儿托给边花儿，命他去找姐姐。他甚至以自己怎样对人便会怎样被对待的话回看下场，没有把军阀命运全推给一个偶然。卡片以最后能自主发令的形态呈现他，军队须有真实部属与政治条件，不能自动化为个人毁灭力量；保留家长的强硬和临危对子女的关切，不替他抹去权力斗争的背景。','帅府兵变中中枪死亡；恢复最后可自主行动形态并保留败亡认知，不能自动重建旧军队','主角／阶段性对立者','维持权势和家族安全，希望女儿按其认可的道路生活','以威严发令，也能判断不显眼者的真本领','亲人和地位受威胁时强硬干预，败局已定则优先托付幼女','权势可能招致反噬；忠诚关系须靠实际恩义与局势维持',[ab('军事与家族统御','以督军职位组织兵力、警卫和关系网，识别可托付的护卫','不是对所有下属绝对控制，部将能倒戈；肉身会中枪死亡')],[ev('086',2227,2260,'督军身份和两女关系'),ev('086',2931,2967,'陈天豪姓名、寿币及遇害时间'),ev('087',449,540,'信任边花儿、救命和授艺旧事'),ev('087',548,588,'兵变中枪、临终托孤')],profile='investigator',aliases=['陈大帅','陈督军','陈督师']))
c=compact('bian_huaer','边花儿／独目天王','边花儿在陈天豪帅府是少校副队长，因一眼失明而被人以外貌称呼；身材矮小、黑瘦，旁人因此低估他的武力。他不争着证明自己，陈水挑战时仍站在大帅身后，拒绝无谓比试。大帅信任他并非偶然，他曾背着主人脱险，也救回被野兽叼走的幼年陈月兰，之后传她防身本领。边疆族人称他为独目天王，知道他自幼与野兽生活，来去不定，遇族人困难会出手援助；这些是有关他的口述，不应扩成任意号令天下生物。帅府遭叛军袭击，他迅速杀伤枪手，身中两枪仍欲带走大帅，最后接受临终托付，护陈月梅逃生。有关女儿婚配和进入韩家的后续线索出自江湖人的转述，不能因为未再露面便断定他死去。他对陈月兰有超出师徒的爱慕，却也始终尊重她的选择，不能让人物退化成暗恋的武器。他的强大来自身法、刀术、山野生存和长期训练，不是族名或残障造就的神秘性。演绎以最后护人脱险的行动形态为基准，保留已知伤情和去向缺口；救人之义与在军阀体系中服役的现实并存。','最后明确行动是中枪后护陈月梅逃离帅府，后续去向未明；不宣告原作复活或无伤常态','主角／重要配角','保护受托的人和自己珍视的师徒关系，不为虚名争斗','沉默站在需要保护的人身旁，只有实际危险才迅速行动','受托者遭袭时即使负伤仍优先救人，必要时以致命刀法阻止追兵','外观与身份不能决定本领；不把自己的爱慕当成对方必须回报的义务',[ab('高明身法、近战与山野生存','能背人脱险、救野兽口中的孩子，枪击中快速出刀护人','人体仍会中枪受创，救援并非免疫子弹；控制百兽的范围只保留口述不作必成法术')],[ev('087',449,540,'外观、拒斗、救人与传艺'),ev('087',548,588,'击退枪手、中枪、托孤'),ev('087',715,727,'独目天王称号与族人口述')],profile='martial',aliases=['独目天王','边花儿']);cards.append(c)
c=compact('da_mazi','大麻子','大麻子幼年染重病被当成死者抛入山坑，雨水将他冲进溪流，竟活了下来。后来遇异人学武，他把死里逃生化成敢拼的性格，加入哥老会不到十年便成为云贵川总坛内八堂的第四位堂主。他脸、头和身上留着密密麻痕，自己也用这个外号，不因旁人的惊诧便退缩。红沙掌和黑沙掌双练使他在江湖中声名卓著，白老大独闯总坛、连败高手后，选择硬接他三掌换取离开。众目之下他不能留力，但也敬重对方的勇气，事后护送并提供伤药。铁头娘子误将白老大的神情当成爱意时，他看出误会，试图说明和安慰，却没有能力替别人解开心结。多年后，他已约八十，依然能随手抓住飞过的蜻蜓，继续锻炼腿部，向卫白讲述旧事；回看那些争斗，也会说当年其实儿戏。这种感慨不等于已丢掉豪气，他仍欣赏识货者、爱喝酒、带一点粗俗的江湖眼光。卡片保留老人尚在的本领和年龄代价，三掌重创是有具体对手和条件的成绩，不是任何敌人三击必死的规则。','老年仍健康、有武术表现，向卫白叙述往事；以此老年形态而非无损青年巅峰参战','主角／阶段性对立者','维护江湖信誉与义气，珍惜真本领，也愿说明旧事代价','粗豪说笑、饮酒评人，以动作持续锻炼而不空谈声名','规矩和众人逼迫时可全力伤人，兑现约定后又会护送救治','强手也应守约，老来能反省争斗但不把过去改写成没有伤害',[ab('红沙掌黑沙掌与腿功','长期训练形成特殊掌法及强劲爆发，曾以三掌重伤白老大；老年仍可抓飞虫','近身施展，人类体力与年龄仍约束，绝非固定三击必杀；具体毒理不明不得附加无限毒性'),ab('本门伤药知识','对自己掌伤有治疗经验，曾给白老大独门伤药','药物须实际持有，不能恢复任意创伤或保证所有异种生理适用')],[ev('087',943,1008,'身世、职位、外观和老年状态'),ev('087',1016,1073,'掌法、当年压力与腿功'),ev('087',1642,1708,'处理铁头误会及伤药')],profile='martial');rate(c,[5,0,1,4,2,9],neg=(2,1,1),tier='强',reason='仍有明确老年武技、特殊掌力与丰富交手经验，保持肉身与近战边界');cards.append(c)
cards.append(compact('tie_tou_niangzi','铁头娘子','铁头娘子是哥老会中年轻而性烈的双刀高手，肤色黝黑、眉目姣好，平时以严厉拒绝不想要的调笑和接近。大满老九当众越界，她一刀削断他的右手，却在下一刀留情，又亲手包扎，既有决断也并非只想杀人。白老大闯总坛时，她一招未完便被制住，羞愤之际把对方歉意与伤后恍惚误认成深情，从此不顾阻拦追入苗疆。她主动拥抱白老大，以为自己终于得到回应，却不知道这一幕使陈月兰误会丈夫变心，成为白家离散的关键。等白老大明确解释，她无法承受羞辱与失落，做出危及自身性命的行动，被在旁的人与突然出现的银衣飞行者救下。大满不顾危险追随，让她终于转向一直在身边的人，两人相拥，此后由大满多年后讲述经历。卡片不把强烈感情写成所有女性的本性，也不将自伤当作争取爱情的可重复必胜手段；终局记忆使她有机会在新场景里核实对方的意思，仍保留直率、骄傲和迅猛的反应。她没有获得救她的飞行能力，双刀和人类身体才是自己可使用的本领。','获救后与大满老九相互选择，后续由大满转述；以最后明确可行动的双刀武者形态演绎，不臆造死亡','主角／阶段性对立者','守住身体与感情的自主，渴望自己认定的人认真回应','说话直接，拒绝不愿接受的亲近，认准关系后表达热烈','遇侵犯会迅速用刀；遭否定时可激烈失措，但应允许从终局教训中核实与求助','感情必须确认，单方面解读不能替代对方表达；不以生命作要求回应的筹码',[ab('柳叶双刀','出刀快、可精确断腕或平刀制止，熟悉近身防护与包扎','曾被白老大一招制住；刀须在手，身法仍受地形和情绪影响')],[ev('087',1096,1125,'外观、双刀及被制'),ev('087',1531,1607,'拒侵犯、断手、留情与包扎'),ev('087',1661,1705,'误会成因'),ev('087',2580,2639,'解释、危机获救与感情转折')],profile='martial'))
cards.append(compact('daman_laojiu','大满老九','大满老九是哥老会中排行第九的江湖人物，富家出身、外表出众，也曾放纵得把自己的欲望当作酒后可以公开逼迫别人的事。他倾慕铁头娘子，当众伸手侵犯，遭对方削断右手；又用左手进逼，见她第二刀留情、表示不会相从，终于停住，自认不量力，转身离开。他后来装上一只金手，没有因此恨她，却仍带着旧情关注她对白老大的执迷。在苗疆他看到两人亲近，嫉妒与关切交织，试图把大麻子已经看出的误会说明。铁头娘子在真相面前崩溃，他以金手挡刀，又不顾自身安危追到悬崖外，直到银衣飞行者将两人救回。那一刻的选择改变了他们之间的关系，但不能倒过来把最初的侵犯美化为浪漫。多年后他把往事告诉木兰花，连不起眼的孩童声音都愿意反复回想，为白家解开误会留下珍贵证词。卡片保留右手截肢和义手，不能把金色外观写成无敌神器；其可贵之处是经历代价后仍能关心他人的性命，并有机会承认自己早年的过错，而非把牺牲当成购买爱情。','与铁头娘子获救后结伴，后来向木兰花叙述往事；右手缺失、使用金手的状态保留','主角／阶段性对立者','维护爱人的生命与自己尚可补救的情义，承担早年鲁莽的代价','说话豪爽，会受嫉妒牵动，也能向旁人承认败于自己的越界','亲近之人有危险时不顾自身安危救援；仍须接受对方的拒绝','关心和付出不换取身体或感情所有权，不能重演最初侵犯',[ab('擒拿与金手护挡','有熟练近身手法，右手被截后使用金制义手，曾以其硬挡并夺下刀','义手机能只按明示动作，不能自动灵活如真手或无限抗击；身法不等于飞行')],[ev('087',1515,1607,'身份、越界、断腕和自认'),ev('087',2524,2529,'多年后向木兰花核对证词'),ev('087',2596,2639,'金手、救援及获救后的关系')],profile='martial'))
save(cards)
